return ['domain'=>'publishpress-hub','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'fi','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 12:21+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Keskitetty hallintakeskus kaikille PublishPress-laajennuksille - asenna, päivitä ja hallinnoi lisenssejä yhdestä dashboardista.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Ole hyvä ja odota, kun lataamme komponenttien esittelyn...','AI Connections'=>'AI-yhteydet','Please wait while we load AI connections...'=>'Ole hyvä ja odota, kun lataamme AI-yhteyksiä...','Please wait while we load the plugins dashboard...'=>'Ole hyvä ja odota, kun lataamme laajennusten dashboardia...','Settings'=>'Asetukset','Please wait while we load the settings page...'=>'Ole hyvä ja odota, kun lataamme asetussivua...','You do not have sufficient permissions to access this page.'=>'Sinulla ei ole riittäviä oikeuksia tämän sivun avaamiseen.','Welcome'=>'Tervetuloa','Please wait while we load the welcome page...'=>'Ole hyvä ja odota, kun lataamme tervetulossivua...','Language pack has not been checked yet.'=>'Kielipakettia ei ole vielä tarkistettu.','Site locale is English. No language pack is downloaded.'=>'Sivuston kieli on englanti. Kielipakettia ei ole ladattu.','No language packs are registered.'=>'Kielipaketteja ei ole rekisteröity.','Language pack directory is not available.'=>'Kielipakettikansio ei ole käytettävissä.','Language pack for %1$s (%2$s) matches %3$s.'=>'Kielipaketti %1$s (%2$s) vastaa %3$s:ää.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Kielipaketti %1$s (%2$s) on asennettu %3$s:lle.','Language pack URL was rejected.'=>'Kielipaketin URL-osoite hylättiin.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Kielipaketin lataaminen epäonnistui %1$s (%2$s). Asennettu paketti jätettiin paikoilleen.','Language pack could not be unpacked.'=>'Kielipakettia ei voitu purkaa.','Language pack is missing a catalog file. The installed pack was left in place.'=>'Kielipaketista puuttuu luettelotiedosto. Asennettu paketti jätettiin paikoilleen.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'Kielipaketin JSON-luettelo on virheellinen. Asennettu paketti jätettiin paikoilleen.','Language pack could not be stored. The installed pack was left in place.'=>'Kielipakettia ei voitu tallentaa. Asennettu paketti jätettiin paikoilleen.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'Kielipaketin PHP-luetteloa ei voitu luoda. Asennettu paketti jätettiin paikoilleen.','Warning: The license for %1$s has expired. %2$s'=>'Varoitus: %1$s:lle myönnetty lisenssi on vanhentunut. %2$s','Manage licenses'=>'Hallitse lisenssejä','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Varoitus: %1$d laajennuksen lisenssiä on vanhentunut: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Lisenssipalvelin hyväksyi avaimen, mutta tämä sivusto ei voinut tallentaa aktiivista lisenssiään. Ole hyvä ja ota yhteyttä tukeen ja mainitse tämä viesti.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'PublishPress-toiminnot %s:lle. Nämä työkalut koskevat vain tätä sivustoa. Jos useat sivustot ovat yhteydessä ja pyydetty sivusto on epäselvä, kysy, mitä sivustoa käyttää ennen työkalun kutsumista. Vahvista kohdesivusto ennen sivustotietojen muuttamista.','WordPress version'=>'WordPress-versio','MCP Adapter version'=>'MCP-sovittimen versio','Not active'=>'Ei käytössä','HTTPS'=>'HTTPS','Available'=>'Saatavilla','Required'=>'Pakollinen','Application passwords'=>'Sovellussalasanat','Unavailable; check WordPress or security plugin settings'=>'Ei saatavilla; tarkista WordPressin tai turvallisuuslaajennuksen asetukset','Registered actions'=>'Rekisteröidyt toiminnot','Selected actions exposed'=>'Valitut toiminnot näkyvissä','Changes saved.'=>'Muutokset tallennettu.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Muutokset tallennettu. Käynnistä AI-sovelluksesi uudelleen tai päivitä sen PublishPress-yhteys päivittääksesi saatavilla olevat toiminnot.','Changes saved. Connect your AI app to continue.'=>'Muutokset tallennettu. Yhdistä AI-sovelluksesi jatkaaksesi.','Changes saved. Select at least one available action to continue.'=>'Muutokset tallennettu. Valitse vähintään yksi saatavilla oleva toiminto jatkaaksesi.','Update WordPress to continue'=>'Päivitä WordPress jatkaaksesi','WordPress 6.9 or newer is required.'=>'WordPress 6.9 tai uudempi vaaditaan.','Open WordPress updates'=>'Avaa WordPress-päivitykset','Install the MCP Adapter plugin'=>'Asenna MCP Adapter -lisäosa','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'Asenna virallinen WordPress MCP Adapter -lisäosa yhdistääksesi AI-palvelusi.','Manage plugins'=>'Hallinnoi lisäosia','Set up MCP Adapter'=>'Aseta MCP Adapter','Use HTTPS to connect your AI'=>'Käytä HTTPS:ää yhdistääksesi AI:si','Both WordPress and site addresses must use HTTPS.'=>'Sekä WordPress- että sivuston osoitteet on käytettävä HTTPS:ää.','Open site settings'=>'Avaa sivuston asetukset','Add a PublishPress plugin with AI actions'=>'Lisää PublishPress-lisäosa AI-toiminnoilla','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'Sinulla ei ole vielä asennettuna mitään PublishPress-lisäosia, jotka tukevat AI-toimintoja.','Open PublishPress plugins'=>'Avaa PublishPress-lisäosat','Allow application passwords for your account'=>'Salli sovellussalasanat tilillesi','Create an application password in your WordPress profile for assisted or manual setup.'=>'Luo sovellussalasana WordPress-profiilissasi avustettua tai manuaalista asennusta varten.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Sovellussalasanat eivät ole saatavilla tilillesi. HTTPS- tai turvallisuuslisäosan asetuksiin voi olla kiinnitettävä huomiota.','Open application passwords'=>'Avaa sovellussalasanat','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'LIITÄ_SOVELLUSSALASANASI_TÄHÄN','Ask my AI to help'=>'Kysy AI:ltani apua','Recommended. Ask your AI for a setup script to run on your computer.'=>'Suositellaan. Kysy AI:lta asennusskriptiä, joka suoritetaan tietokoneellasi.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Yhdistä AI-sovellukseni PublishPressiin. Luo asennusskripti ja anna minulle tarkka terminaalikomento sen suorittamiseksi.

1. Pyydä minua valitsemaan AI-sovellukseni ja käyttöjärjestelmäni (Windows, macOS tai Linux). Käytä interaktiivisia valintoja, jos saatavilla, muuten numeroituja vaihtoehtoja.
2. Luo skripti käyttämällä tiedostotyökaluja. Pyydä tarvittaessa erityistä lupaa. Jos et voi kirjoittaa paikallisesti, liitä ladattava skripti. Turvaudu vain koodiin tallennusohjeiden kanssa, kun kumpikaan ei ole mahdollista. Käytä PowerShelliä Windowsissa ja sopivaa skriptiä macOS:ssä tai Linuxissa. Älä pysähdy selittämään pääsyrajoituksia tai tarjoa vain JSON:ia.
3. Määritä tämä paikallinen stdio-palvelin:
Nimi: %3$s
Näkyvä nimi: %4$s
Komentosarja: npx
Argumentit: -y @automattic/mcp-wordpress-remote@latest
Ympäristö: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Lue WP_API_PASSWORD piilotetusta terminaalikehotteesta.
Hubin kirjoitusoikeus: %5$s. Vain erikseen valitut toiminnot ovat näkyvissä.
4. Tarkista Node.js ja npx. Jos puuttuu, linkitä viralliseen asennustyökaluun ja pyydä minua avaamaan terminaali uudelleen. Varmista olemassa olevat asetukset. Käytä JSON/TOML-jäsentäjää tai tuettua asiakas komentoa yhdistääksesi vain tämä palvelin, säilyttäen muut asetukset ja sivustot. Pysähdy virheellisessä kokoonpanossa tai ristiriitaisessa päätepisteessä. Jos vaihdat vanhan PublishPress-työpöytälisäosan tälle sivustolle, ohjaa minut poistamaan vain se lisäosa välttääksesi kaksoisyhteyksiä. Sitoudu polkuihin ja arvoihin turvallisesti.
5. Anna lyhyet suoritus-, uudelleenkäynnistys- ja hyväksymisohjeet. Vahvista yhteyden kautta tai anna minulle kehotus testata sovelluksessa: vahvista sivuston URL-osoite, luettele todelliset työkalut ja suorita vain lukuoikeudellinen haku. Ilmoita, ovatko kirjoitusvälineet saatavilla. Jos odotettuja kirjoitusvälineitä puuttuu, pyydä minua tarkistamaan Salli toiminnot, jotka muuttavat sivuston tietoja ja valitut toiminnot Hubissa, ja päivitä sitten yhteys. Älä väitä menestystä vain tallennetusta kokoonpanosta. Älä testaa kirjoituksia asennuksen aikana. Selvennä kohdesivustoa, kun se on epäselvä, ja pyydä tarkistamaan ennen sivuston tietojen muuttamista.','enabled'=>'käytössä','disabled'=>'pois käytöstä','Set up manually'=>'Aseta manuaalisesti','Copy the configuration into your MCP client.'=>'Kopioi kokoonpano MCP-asiakkaaseesi.','Actions available through PublishPress Hub.'=>'Toiminnot, jotka ovat saatavilla PublishPress Hubin kautta.','List WordPress users'=>'Luettele WordPress-käyttäjät','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Etsi käyttäjiä nimen tai roolin mukaan. Valinnainen primitiivinen kyvykkyysfiltteri tarkistaa tehokkaan pääsyn jokaiselle ehdokassivulle. Vieraile kaikilla total_pages-sivuilla, vaikka suodatettu sivu olisi tyhjää. Sähköpostiosoitteita tai salaisuuksia ei palauteta.','Get WordPress user capabilities'=>'Hanki WordPress-käyttäjän kyvykkyydet','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Tunnista tarkasti yksi user_id tai käyttäjänimi ja palauta heidän identiteettinsä, roolinsa ja tehokkaat primitiiviset kyvykkyytensä. Älä koskaan arvaa käyttäjä-ID:tä. Kohdekohtaiset käyttöoikeudet vaativat erillisen tarkistuksen kyseiselle kohteelle.','Find WordPress content'=>'Etsi WordPress-sisältöä','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Hae luettavia julkaisuja, sivuja tai REST-rajapintojen mukautettua viestityyppiä. Palauttaa todelliset ID:t, otsikot ja pysyvät linkit. Käytä post_type=page sivuille. Ratkaise epäselviä otsikoita ennen URL:n käyttöä. Oletustila on julkaistu. Yksityiset ja luonnospyynnöt valvovat WordPressin käyttöoikeuksia.','List WordPress post types'=>'Luettele WordPressin viestityypit','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Luettele luettavat REST-rajapintojen mukautetut viestityypit ja jokaiselle tyypille käytetyt kyvykkyysnimet. Käytä näitä nimiä sisällön hakuissa ja käyttöoikeuskysymyksissä.','WordPress'=>'WordPress','Create WordPress user'=>'Luo WordPress-käyttäjä','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Luo uusi käyttäjätili tunnetulla käyttäjätunnuksella, sähköpostilla ja yhdellä muokattavalla roolilla. Kysy puuttuvia tietoja. WordPress validoi roolihakemusten oikeudet. MCP hylkää ylläpitäjä- ja kaikki roolit, jotka antavat ylläpitäjän tason oikeudet. Salasana luodaan yksityisesti. Oletuksena WordPress lähettää käyttäjälle sähköpostitse salasanan asetuslinkin. Älä koskaan arvaa sähköpostia tai pyydä salasanaa chatissa.','Create WordPress content'=>'Luo WordPress-sisältö','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Luo julkaisu, sivu tai REST-ominaisuuksilla varustettu mukautettu postityyppi. Käytä post_type=page sivuille. Oletuksena on luonnos. Julkaise tai aikatauluta vain pyydettäessä. WordPress tarkistaa luomisen, julkaisemisen ja kirjoittajavalinnan oikeudet. Palauttaa todellisen ID:n ja permalinkin.','Update WordPress content'=>'Päivitä WordPress-sisältö','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'Muokkaa olemassa olevaa julkaisua, sivua tai REST-ominaisuuksilla varustettua mukautettua postausta sen vahvistetulla ID:llä. Etsi sisältö ensin, jos ID ei ole tiedossa. Ainoastaan toimitetut kentät muuttuvat. WordPress tarkistaa objektin, julkaisemisen ja kirjoittajavalinnan oikeudet. Poistoa, satunnaista metatietoa tai vaihtoehtoja ei tueta.','Use the exact input types shown in discovery.'=>'Käytä tarkkoja syöttötietotyyppejä, jotka on esitetty löytämisessä.','You cannot list users.'=>'Et voi luetella käyttäjiä.','Provide either a user ID or an exact username.'=>'Toimita joko käyttäjä-ID tai tarkka käyttäjätunnus.','No matching user belongs to this site.'=>'Tälle sivustolle ei kuulu yhtään vastaavaa käyttäjää.','You cannot inspect this user.'=>'Et voi tarkastella tätä käyttäjää.','Choose a REST-enabled post type.'=>'Valitse REST-ominaisuuksilla varustettu postityyppi.','This post type does not support content lookup.'=>'Tämä postityyppi ei tue sisällön hakemista.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'MCP-työkalut eivät voi luoda käyttäjiä, joilla on ylläpitäjätason pääsy. Käytä WordPressin Käyttäjät-näyttöä tälle muutokselle.','Provide at least one content field to update.'=>'Toimita vähintään yksi kenttä, jota päivitetään.','Choose an existing REST-enabled post type.'=>'Valitse olemassa oleva REST-ominaisuuksilla varustettu postityyppi.','This post type does not support content writes.'=>'Tämä postityyppi ei tue sisällön kirjoittamista.','You cannot perform this operation.'=>'Et voi suorittaa tätä toimintoa.','Object must be loaded before initializing.'=>'Objekti on ladattava ennen alustamista.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Tätä lisenssiavainta hallitaan tiedostossa wp-config.php, eikä sitä voi muokata Hubista.','No license key found'=>'Lisenssiavainta ei löytynyt','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Tätä lisenssiavainta hallitaan tiedostossa wp-config.php, eikä sitä voi poistaa käytöstä Hubista.','Invalid conflict resolution request.'=>'Virheellinen konfliktin ratkaisupyyntö.','The selected plugin is not available for activation.'=>'Valittua lisäosaa ei ole saatavilla aktivoitavaksi.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Siivous keskeytettiin, koska valittu lisäosa ei ole aktiivinen tai toinen versio on edelleen ladattu. Kumpikaan kopio ei poistettu.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Valittu lisäosa on aktiivinen, mutta toista versiota ei voitu poistaa. Poista se Lisäosat-näytöltä.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Valittu lisäosa ei ole enää aktiivinen. Aktivoi se uudelleen Lisäosat-näytöltä.','No existing license key was found for this plugin.'=>'Tätä lisäosaa varten ei löytynyt olemassa olevaa lisenssiavainta.','Database Tables'=>'Tietokantataulut','PublishPress Plugins'=>'PublishPress-lisäosat','PublishPress Hub Debug Log'=>'PublishPress Hubin virheenkorjauslokit','Debug Log'=>'Virheenkorjauslokit','The debug log is empty.'=>'Virheenkorjauslokit ovat tyhjät.','Version'=>'Versio','Debug Mode'=>'Virheenkorjaustila','Enabled'=>'Oletettu','Disabled'=>'Poistettu käytöstä','Generated At'=>'Luotu','Plugins'=>'Lisäosat','No PublishPress plugins found.'=>'Ei löytynyt PublishPress-lisäosia.','Tables'=>'Taulukot','No database table information was available.'=>'Tietokantataulun tietoja ei ollut saatavilla.','Size'=>'Koko','Engine'=>'Moottori','Rows'=>'Rivit','Collation'=>'Lajittelu','Charset'=>'Merkkijono','Total Database Size'=>'Kokonaiskannan koko','Not installed'=>'Ei asennettu','Active'=>'Aktiivinen','Inactive'=>'Ei aktiivinen','unknown'=>'tuntematon','License'=>'Lisenssi','Free plugin not set for plugin family: %s'=>'Ilmainen laajennus ei ole asetettu laajennusperheelle: %s','Pro plugin not set for plugin family: %s'=>'Pro-laajennusta ei ole asetettu laajennusperheelle: %s','License activation error. Please try again later or contact support for help.'=>'Lisenssin aktivointivirhe. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','License deactivation error. Please try again later or contact support for help.'=>'Lisenssin deaktivoimivirhe. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','This license is currently disabled. Please contact support for help.'=>'Tämä lisenssi on tällä hetkellä pois käytöstä. Ota yhteyttä tukeen saadaksesi apua.','This license has expired. Please contact support to renew it.'=>'Tämän lisenssin voimassaolo on päättynyt. Ota yhteyttä tukeen uusimista varten.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Tätä lisenssiavainta ei voitu aktivoida. Se voi olla virheellinen, estetty tai ei ole valtuutettu tälle laajennukselle. Varmista avain ja ota yhteyttä PublishPress-tukeen, jos ongelma jatkuu.','This license cannot be used for this plugin. Please contact support for help.'=>'Tätä lisenssiä ei voida käyttää tälle laajennukselle. Ota yhteyttä tukeen saadaksesi apua.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Tämä lisenssi ei vastaa laajennusta, jota yrität aktivoida. Ota yhteyttä tukeen saadaksesi apua.','License key does not match our records. Please contact support for assistance.'=>'Lisenssiavain ei vastaa tietojamme. Ota yhteyttä tukeen saadaksesi apua.','No license key provided. Please enter a valid license key.'=>'Lisenssiavainta ei ole annettu. Anna voimassa oleva lisenssiavain.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'Verkkosivustosi URL-osoite on tarpeen lisenssin aktivoimiseksi. Anna voimassa oleva verkkosivuston URL-osoite jatkaaksesi.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Lisenssin aktivointiraja on saavutettu. Ota yhteyttä tukeen päivittääksesi tai poistaaksesi käytöstä toisella sivustolla.','This license cannot be activated. Please contact support for help.'=>'Tätä lisenssiä ei voida aktivoida. Ota yhteyttä tukeen saadaksesi apua.','License server error. Please try again later or contact support for help.'=>'Lisenssipalvelimen virhe. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Lisenssipalvelin palautti virheellisen vastauksen. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','This license is inactive for this site. Please contact support for help.'=>'Tämä lisenssi ei ole aktiivinen tälle sivustolle. Ota yhteyttä tukeen saadaksesi apua.','Plugin activation failed. Please try again later or contact support for help.'=>'Laajennuksen aktivointi epäonnistui. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','This action is not possible because the plugin is already installed.'=>'Tämä toiminto ei ole mahdollista, koska laajennus on jo asennettu.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Laajennuksen deaktivoiminen epäonnistui. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','Plugin family not found. Please contact support for help.'=>'Laajennusperhettä ei löytynyt. Ota yhteyttä tukeen saadaksesi apua.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Tämä toiminto ei ole mahdollista, koska sekä ilmainen että pro-versio on asennettu. Poista yksi versio käytöstä jatkaaksesi.','Plugin installation failed. Please contact support for help.'=>'Laajennuksen asennus epäonnistui. Ota yhteyttä tukeen saadaksesi apua.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Tämä toiminto ei ole mahdollista, koska laajennusta ei ole aktivoitu. Aktivoi laajennus ja yritä uudelleen.','Plugin not found in our available plugins list. Please contact support for help.'=>'Laajennusta ei löytynyt käytettävissä olevien laajennusten luettelosta. Ota yhteyttä tukeen saadaksesi apua.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Tämä toiminto ei ole mahdollista, koska laajennusta ei ole asennettu. Asenna laajennus ja yritä uudelleen.','Unknown license server error. Please try again later or contact support for help.'=>'Tuntematon lisenssipalvelimen virhe. Yritä uudelleen myöhemmin tai ota yhteyttä tukeen saadaksesi apua.','Sell digital products, programs, and services from your website.'=>'Myy digitaalisia tuotteita, ohjelmia ja palveluja verkkosivustoltasi.','Create and manage tags, categories, and taxonomy terms.'=>'Luo ja hallinnoi tageja, kategorioita ja taksonomian termejä.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Järjestä taksonomian termejä ryhmiin ja näytä niitä pilvissä, välilehdissä ja listoilla.','Define tasks that authors must complete before publishing.'=>'Määritä tehtävät, jotka kirjoittajien on suoritettava ennen julkaisemista.','Control who can edit and view your content.'=>'Hallitse, kuka voi muokata ja katsella sisältöäsi.','Create, manage and display authors for your content.'=>'Luo, hallinnoi ja näytä kirjoittajia sisältösi varten.','All the tools you need to improve the block editor.'=>'Kaikki työkalut, joita tarvitset lohkoeditorin parantamiseen.','Control your admin area and user roles.'=>'Hallitse hallinta-aluettasi ja käyttäjäroolejasi.','Schedule changes to your posts.'=>'Aikatauluta muutoksia viesteihisi.','Organize, schedule, and plan your publishing.'=>'Järjestä, aikatauluta ja suunnittele julkaisemista.','Approve and schedule new versions to your published posts.'=>'Hyväksy ja aikatauluta uudet versiot julkaistuista viesteistäsi.','Organize your posts into issues or series.'=>'Järjestä viestisi numeroiksi tai sarjoiksi.','Create custom URLs for your posts and external links.'=>'Luo mukautettuja URL-osoitteita viesteillesi ja ulkoisille linkeille.','Create custom statuses and publishing workflows.'=>'Luo mukautettuja statuksia ja julkaisemisprosesseja.','Dependency "%s" not found in container.'=>'Riippuvuus "%s" ei löytynyt säiliöstä.','Error validating license: %s'=>'Virhe lisenssin vahvistamisessa: %s','Error getting license info: %s'=>'Virhe lisenssitietojen hakemisessa: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Lisenssipalvelin hylkäsi tämän pyynnön. Tämä voi tapahtua, kun lisenssiavain tai sivusto on estetty. Ota yhteyttä PublishPress-tukeen saadaksesi apua.','Too many requests. Please try again later.'=>'Liian monta pyyntöä. Yritä myöhemmin uudelleen.','An error occurred while processing your request.'=>'Virhe tapahtui käsiteltäessä pyyntöäsi.','Template not found: %s'=>'Mallia ei löytynyt: %s','Path cannot be empty'=>'Polku ei voi olla tyhjää','File extension cannot be empty'=>'Tiedostopäätteet eivät voi olla tyhjät','Invalid file path: null byte detected'=>'Virheellinen tiedostopolku: havaittu nollabitti','Invalid file path: directory traversal detected'=>'Virheellinen tiedostopolku: havaittu hakemiston ylitys','Invalid file path: parent directory does not exist: %s'=>'Virheellinen tiedostopolku: vanhempaa hakemistoa ei ole olemassa: %s','Invalid file path: unable to resolve path'=>'Virheellinen tiedostopolku: polkua ei voitu ratkaista','Invalid file path: operation not allowed outside permitted directories'=>'Virheellinen tiedostopolku: toimintoa ei sallita sallitun hakemiston ulkopuolella','Download URL failed WordPress validation'=>'Lataus-URL epäonnistui WordPressin vahvistuksessa','Downloaded plugin file does not exist'=>'Ladattua liitännäistiedostoa ei ole olemassa','Downloaded plugin file is empty'=>'Ladattu liitännäistiedosto on tyhjää','Cannot read downloaded plugin file'=>'Ei voida lukea ladattua liitännäistiedostoa','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'Ladattu tiedosto ei ole voimassa oleva ZIP-arkisto. Lataus-URL saattaa palauttaa virhesivun.','Failed to unzip plugin file: %s'=>'Liitännäistiedoston purku epäonnistui: %s','Failed to unzip plugin file'=>'Liitännäistiedoston purku epäonnistui','Failed to activate plugin: %s'=>'Liitännäisen aktivointi epäonnistui: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'Ratkaise konfliktit verkossa aktiivisten liitännäisten osalta Verkkohallinnasta.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'Aktivoinnin palautus epäonnistui. Molemmat liitännäiskopiot säilytettiin. Palauta aiempi versio Liitännäiset-näytöltä.','The other plugin could not be deactivated.'=>'Toista liitännäistä ei voitu deaktivoida.','The selected plugin did not remain active.'=>'Valittua liitännäistä ei säilytetty aktiivisena.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'Valittua lisäosaa ei voitu aktivoida. Yhtään kopiota ei poistettu ja aikaisemmat aktivointiasetukset palautettiin.','Failed to delete plugin: %s'=>'Lisäosan poistaminen epäonnistui: %s','No update available for this plugin'=>'Tälle lisäosalle ei ole saatavilla päivitystä','Invalid update information for this plugin'=>'Virheelliset päivitystiedot tälle lisäosalle','Update package not available'=>'Päivityspaketti ei ole saatavilla','Failed to update plugin: %s'=>'Lisäosan päivittäminen epäonnistui: %s','Plugin update failed'=>'Lisäosan päivitys epäonnistui','Invalid download URL provided'=>'Virheellinen lataus-URL annettu','Download URL must use HTTP or HTTPS protocol'=>'Lataus-URL:n on käytettävä HTTP- tai HTTPS-protokollaa','Download URL is not from an allowed domain: %s'=>'Lataus-URL ei ole sallitulta alueilta: %s','Could not create a temporary package file'=>'Väliaikaisen pakettitiedoston luonti epäonnistui','Failed to download plugin: %s'=>'Lisäosan lataaminen epäonnistui: %s','The plugin package download failed'=>'Lisäospaketin lataaminen epäonnistui','Failed to get plugin information: %s'=>'Lisäosan tietojen saaminen epäonnistui: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'MCP-sovitinta ei voitu asentaa tai aktivoida. Käytä lisäosien sivua tai ota yhteyttä isäntään.','MCP Adapter activated.'=>'MCP-sovitin aktivoitu.','ERR'=>'ERR','.'=>'.']];